"""Calculates chao1 variance, bias-corrected.

    From EstimateS manual, equation 6.
    """
def chao1_var_bias_corrected(singles: Any, doubles: Any) -> object {
    (s, d) = (float(singles), float(doubles));
    return (
        ((s * (s - 1)) / (2 * (d + 1)))
        + ((s * (((2 * s) - 1) ** 2)) / (4 * ((d + 1) ** 2)))
        + (((s ** 2) * d * ((s - 1) ** 2)) / (4 * ((d + 1) ** 4)))
    );
}

test_blocks:
test "t0" {
    assert (chao1_var_bias_corrected(1, 1) == chao1_var_bias_corrected(1, 1));;
}

test "t1" {
    assert (chao1_var_bias_corrected(0, 1) == 0.0);;
}

test "t2" {
    assert (chao1_var_bias_corrected(0, 0) == 0);;
}

test "t3" {
    assert (chao1_var_bias_corrected(0, 0) == 0.0);;
}

test "t4" {
    assert (chao1_var_bias_corrected(0, 2) == 0.0);;
}
